function [o] = quad_overlap(lo, hi, a, b)
%QUAD_OVERLAP  The length of the overlap of [lo, hi] and [a, b] (none when they do not overlap).
%   lo: real[1] (passed a plain number)
%   hi: real[1] (passed a plain number)
%   a: real[1] (passed a plain number)
%   b: real[1] (passed a plain number)
%   returns o: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    o = 0;
    top = asils.pc.choose((b < hi), b, hi);
    bot = asils.pc.choose((a > lo), a, lo);
    w = (top - bot);
    o = asils.pc.choose((w > 0), w, 0);
end
